        return False, mst_path, mst_path_len

    mst_vertex_heap = []
    mst_path = {}
    path_len = 0

    # Initialize the priority queue with the start node
    heappush(mst_vertex_heap, (path_len, start))
    visited = {}
    path = [start]
    mst_path[start] = True

    # Run DFS to find the MST path
    while mst_vertex_heap:
        path_len, current_node = heappop(mst_vertex_heap)
        visited[current_node] = True

        if current_node == goal:
            return path

        for neighbor in graph[current_node]:
            if not visited[neighbor]:
